using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents still use "Discriminator", so preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF 9 id format changed from "EntityType|Key" to "Key".
            // Existing documents use "Blog|<key>", so opt in to the legacy format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF.
            // EF 9 now throws instead of silently ignoring. Remove HasIndex and use
            // the Azure portal to manage Cosmos indexing policy.
            // (HasIndex call removed)
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Existing raw SQL queries (SELECT * FROM c WHERE c.Discriminator = 'Blog')
    // must keep using "Discriminator", NOT "$type", to match existing documents.
}

